// One floating prompt over the nearest thing a player can use, and the buttons that use it. Client only.
//
//   addInteractions(() => [{ key: 'lever', position: {x, y, z}, range: 2, height: 1,
//     actions: [{ verb: 'Pull', button: 'primary', run: (pressed) => { if (pressed) pull() } }] }])
//
// addInteractions(provider) adds a function asked every frame for candidates; it returns a remover. The nearest
//   candidate within its `range` (metres across the floor, default 2) that has actions gets the label, drawn
//   `height` metres (default 0.8) above its position: "[E] Pull" on desktop, just "Pull" on a phone. A candidate
//   with `position: null` is the fallback used when nothing is near (what to do with a held item): its line
//   shows in the bottom HUD slot instead.
// button 'primary' is E (the phone's main action button), 'secondary' is F (its second button). An action with
//   `hold: true` gets run(true) when the button goes down and run(false) when it is released or the player walks
//   away; any other action gets run(true) on press only.
// sayNotice(text, seconds?) shows a short line in the bottom HUD slot (why an action did nothing).
// Verbs are plain strings, so a script can pass them in the player's language. The prompt reads InputAction
//   itself; the script using it declares its phone buttons with declareInteractButtons(secondaryIcon?): E with
//   the pick-up icon and jump, plus F with that icon when the script has a secondary action. It is declared
//   here, not in the script, so a prefab that leaves F off never names it and the phone check does not ask for it.
import {
  Billboard,
  BillboardMode,
  InputAction,
  PointerEventType,
  TextShape,
  Transform,
  VisibilityComponent,
  engine,
  inputSystem,
  type Entity
} from '@dcl/sdk/ecs'
import { isMobile } from '@dcl/sdk/platform'
import { actionIcon, type ActionIconName } from './actionIcons'
import { declareTouchButtons, type TouchButton } from './hudLayout'
import { localPlayerPosition } from './playerPositions'
import { mountInteractHint } from './interactHint'
import { nearestCandidate, promptText, type PromptButton, type Vec3 } from './pure/interactPick'

export type { PromptButton }

export interface PromptAction {
  verb: string
  button: PromptButton
  hold?: boolean
  run(pressed: boolean): void
}

export interface PromptCandidate {
  key: string
  position: Vec3 | null
  range?: number
  height?: number
  actions: PromptAction[]
}

interface Holding { key: string; run(pressed: boolean): void; since: number }

interface PromptState {
  providers: Array<() => PromptCandidate[]>
  label: Entity | null
  text: string
  hint: string
  notice: string
  noticeUntil: number
  holding: Holding | null
  frame: number
  mounted: boolean
}

const KEY = '__dclInteract_v1'
const LABEL_HEIGHT = 0.8

function isPromptState(value: unknown): value is PromptState {
  return typeof value === 'object' && value !== null && 'providers' in value && Array.isArray(value.providers) &&
    'holding' in value && 'mounted' in value
}

function prompt(): PromptState {
  const globals = globalThis as unknown as Record<string, unknown>
  const current = globals[KEY]
  if (isPromptState(current)) return current
  const created: PromptState = { providers: [], label: null, text: '', hint: '', notice: '', noticeUntil: 0, holding: null, frame: 0, mounted: false }
  globals[KEY] = created
  return created
}

function mount(state: PromptState): void {
  if (state.mounted) return
  state.mounted = true
  mountInteractHint(() => (Date.now() < state.noticeUntil ? state.notice : state.hint))
  engine.addSystem(promptSystem, undefined, 'runtime-interact-prompt')
}

export function addInteractions(provider: () => PromptCandidate[]): () => void {
  const state = prompt()
  state.providers.push(provider)
  mount(state)
  return () => { state.providers = state.providers.filter((other) => other !== provider) }
}

export function sayNotice(text: string, seconds = 2.5): void {
  const state = prompt()
  state.notice = text
  state.noticeUntil = Date.now() + seconds * 1000
  mount(state)
}

function candidates(state: PromptState): PromptCandidate[] {
  const out: PromptCandidate[] = []
  for (const provider of state.providers) {
    try {
      for (const candidate of provider()) if (candidate.actions.length > 0) out.push(candidate)
    } catch (e) {
      console.error('[interactPrompt] a provider failed:', e)
    }
  }
  return out
}

function showLabel(state: PromptState, target: PromptCandidate | null, text: string): void {
  if (target === null || target.position === null || text === '') {
    if (state.label !== null) VisibilityComponent.createOrReplace(state.label, { visible: false })
    return
  }
  if (state.label === null) {
    state.label = engine.addEntity()
    Billboard.create(state.label, { billboardMode: BillboardMode.BM_ALL })
  }
  const at = target.position
  Transform.createOrReplace(state.label, { position: { x: at.x, y: at.y + (target.height ?? LABEL_HEIGHT), z: at.z } })
  VisibilityComponent.createOrReplace(state.label, { visible: true })
  if (text === state.text && TextShape.has(state.label)) return
  state.text = text
  TextShape.createOrReplace(state.label, {
    text,
    fontSize: 2,
    textColor: { r: 1, g: 1, b: 1, a: 1 },
    outlineColor: { r: 0, g: 0, b: 0 },
    outlineWidth: 0.15
  })
}

function release(state: PromptState): void {
  const holding = state.holding
  state.holding = null
  if (holding !== null) holding.run(false)
}

function promptSystem(): void {
  const state = prompt()
  state.frame++
  const usable = candidates(state)
  const near = nearestCandidate(usable, localPlayerPosition())
  const target = near ?? usable.find((candidate) => candidate.position === null) ?? null
  const phone = isMobile()
  const text = target === null ? '' : promptText(target.actions, phone)
  showLabel(state, near, text)
  state.hint = target !== null && target.position === null ? text : ''

  if (state.holding !== null && state.holding.key !== target?.key) release(state)
  if (target === null) return
  if (inputSystem.isTriggered(InputAction.IA_PRIMARY, PointerEventType.PET_DOWN)) {
    target.actions.find((action) => action.button === 'primary')?.run(true)
  }
  const secondary = target.actions.find((action) => action.button === 'secondary')
  if (secondary !== undefined && state.holding === null && inputSystem.isTriggered(InputAction.IA_SECONDARY, PointerEventType.PET_DOWN)) {
    secondary.run(true)
    if (secondary.hold === true) state.holding = { key: target.key, run: secondary.run, since: state.frame }
  }
  // a release the frame never reported (focus lost, a modal) must not leave the action running
  const holding = state.holding
  if (holding !== null && holding.since !== state.frame &&
    (inputSystem.isTriggered(InputAction.IA_SECONDARY, PointerEventType.PET_UP) || !inputSystem.isPressed(InputAction.IA_SECONDARY))) {
    release(state)
  }
}

/** The phone buttons an interaction uses, each with its action's icon; returns the removal. */
export function declareInteractButtons(secondary?: ActionIconName): () => void {
  const buttons: TouchButton[] = [
    { action: InputAction.IA_PRIMARY, icon: actionIcon('pick-up') },
    { action: InputAction.IA_JUMP, icon: actionIcon('jump') }
  ]
  if (secondary !== undefined) buttons.push({ action: InputAction.IA_SECONDARY, icon: actionIcon(secondary) })
  return declareTouchButtons(buttons, { main: InputAction.IA_PRIMARY })
}
